/// <summary>
/// X++ wrapper over the <c>AtomicAx.Zpl.Render</c> library. Renders ZPL to one PNG per
/// ^XA..^XZ label block entirely in-process.
/// </summary>
public final class AAXZplRenderService
{
    private const str DimensionsMissingExceptionType = 'AtomicAx.Zpl.Render.ZplDimensionsMissingException';
}

Method.Source:
/// <summary>
/// Renders ZPL to a list of PNG images, one container per ^XA..^XZ label block. When the label
/// declares no size and the caller supplies none, the render is retried with the Warehouse
/// management parameter defaults. Renderer errors surface as a readable error.
/// </summary>
/// <param name = "_zpl">The final, token-substituted ZPL.</param>
/// <param name = "_dpmm">The print density in dots per millimeter; 0 uses the configured default.</param>
/// <param name = "_widthMm">The label width in millimeters; 0 uses the ^PW declared in the ZPL.</param>
/// <param name = "_heightMm">The label height in millimeters; 0 uses the ^LL declared in the ZPL.</param>
/// <returns>A <c>List</c> of <c>Types::Container</c> values, one PNG per label block.</returns>
public static List renderToPngList(str _zpl, int _dpmm = 0, real _widthMm = 0, real _heightMm = 0)
{
    WHSParameters p = WHSParameters::find();

    // Resolve the density up front so the renderer can parse the label's own ^PW/^LL
    int dpmm = _dpmm > 0 ? _dpmm : p.aaxPreviewDefaultDpmm();

    try
    {
        return AAXZplRenderService::renderOnce(_zpl, dpmm, _widthMm, _heightMm);
    }
    catch (Exception::CLRError)
    {
        System.Exception clrException = CLRInterop::getLastException();

        if (AAXZplRenderService::containsExceptionType(clrException, DimensionsMissingExceptionType))
        {
            // Retry with the parameter defaults when the label declares no size
            try
            {
                return AAXZplRenderService::renderOnce(
                    _zpl,
                    dpmm,
                    _widthMm > 0 ? _widthMm : p.aaxPreviewDefaultWidthMm(),
                    _heightMm > 0 ? _heightMm : p.aaxPreviewDefaultHeightMm());
            }
            catch (Exception::CLRError)
            {
                clrException = CLRInterop::getLastException();
                throw error(strFmt("@AAXWarehouseTools:RenderFailed",
                    AAXZplRenderService::innermostMessage(clrException)));
            }
        }

        throw error(strFmt("@AAXWarehouseTools:RenderFailed",
            AAXZplRenderService::innermostMessage(clrException)));
    }
}

/// <summary>
/// Performs a single render pass. CLR exceptions bubble up to the caller.
/// </summary>
/// <param name = "_zpl">The final, token-substituted ZPL.</param>
/// <param name = "_dpmm">The print density in dots per millimeter.</param>
/// <param name = "_widthMm">The label width in millimeters, or 0 to use the ZPL.</param>
/// <param name = "_heightMm">The label height in millimeters, or 0 to use the ZPL.</param>
/// <returns>A <c>List</c> of <c>Types::Container</c> values, one PNG per label block.</returns>
private static List renderOnce(str _zpl, int _dpmm, real _widthMm, real _heightMm)
{
    List pngList = new List(Types::Container);
    int  pngCount;
    int  i;

    // Use the X++-friendly result wrapper since X++ cannot declare generic CLR types
    AtomicAx.Zpl.Render.ZplRenderResult renderResult =
        AtomicAx.Zpl.Render.ZplRenderService::RenderToPngs(_zpl, _dpmm, _widthMm, _heightMm);

    pngCount = renderResult.get_Count();

    for (i = 0; i < pngCount; i++)
    {
        pngList.addEnd(AAXZplRenderService::bytesToContainer(renderResult.GetPng(i)));
    }

    return pngList;
}

/// <summary>
/// Converts a CLR byte array to an X++ container.
/// </summary>
/// <param name = "_bytes">The CLR byte array.</param>
/// <returns>The bytes as an X++ container.</returns>
private static container bytesToContainer(System.Byte[] _bytes)
{
    System.IO.MemoryStream memoryStream = new System.IO.MemoryStream(_bytes);
    Binary binary = Binary::constructFromMemoryStream(memoryStream);
    return binary.getContainer();
}

/// <summary>
/// Rotates a PNG image clockwise by the given number of quarter turns. Renderer errors surface
/// as a readable error.
/// </summary>
/// <param name = "_png">The source PNG as an X++ <c>container</c>.</param>
/// <param name = "_quarterTurnsClockwise">The number of quarter turns clockwise; 0 returns the input unchanged.</param>
/// <returns>The rotated PNG as an X++ <c>container</c>.</returns>
public static container rotatePng(container _png, int _quarterTurnsClockwise)
{
    try
    {
        // Convert the container to a CLR byte array
        System.IO.MemoryStream sourceStream = AAXZplRenderService::pngContainerToStream(_png);
        System.Byte[] sourceBytes = sourceStream.ToArray();

        System.Byte[] rotatedBytes =
            AtomicAx.Zpl.Render.ZplRenderService::RotatePng(sourceBytes, _quarterTurnsClockwise);

        return AAXZplRenderService::bytesToContainer(rotatedBytes);
    }
    catch (Exception::CLRError)
    {
        System.Exception clrException = CLRInterop::getLastException();
        throw error(strFmt("@AAXWarehouseTools:RenderFailed",
            AAXZplRenderService::innermostMessage(clrException)));
    }
}

/// <summary>
/// Converts a PNG container to a memory stream for the stream-based file APIs.
/// </summary>
/// <param name = "_png">The PNG as an X++ <c>container</c>.</param>
/// <returns>A memory stream holding the PNG bytes.</returns>
public static System.IO.MemoryStream pngContainerToStream(container _png)
{
    Binary binary = Binary::constructFromContainer(_png);
    return binary.getMemoryStream();
}

/// <summary>
/// Walks the inner exception chain looking for a CLR exception of the given full type name.
/// </summary>
/// <param name = "_exception">The outermost CLR exception.</param>
/// <param name = "_typeFullName">The full type name to look for.</param>
/// <returns>True if an exception of the given type is found in the chain.</returns>
private static boolean containsExceptionType(System.Exception _exception, str _typeFullName)
{
    System.Exception current = _exception;

    while (current != null)
    {
        System.Type exceptionType = current.GetType();
        if (exceptionType.get_FullName() == _typeFullName)
        {
            return true;
        }
        current = current.get_InnerException();
    }

    return false;
}

/// <summary>
/// Builds a readable message from the full CLR exception chain, outer to inner.
/// </summary>
/// <param name = "_exception">The outermost CLR exception.</param>
/// <returns>The messages of the exception chain, one per line.</returns>
private static str innermostMessage(System.Exception _exception)
{
    str result;
    System.Exception current = _exception;

    while (current != null)
    {
        result += (result ? '\n' : '') + current.get_Message();
        current = current.get_InnerException();
    }

    return result;
}
